value.número_cliente:
={{(() => {
  let raw = $('normalizeContext').item.json.whatsAppLead || "";               // pega o número do item
  let digits = raw.replace(/\D/g, "");        // remove tudo que não é dígito

  // remove o prefixo 55 se existir
  if (digits.startsWith("55")) {
    digits = digits.slice(2);
  }

  // se tiver 10 dígitos, adiciona o 9 depois do DDD
  if (digits.length === 10) {
    digits = digits.slice(0,2) + "9" + digits.slice(2);
  }

  // formata com espaços: XX X XXXXXXXX
  return `${digits.slice(0,2)} ${digits.slice(2,3)} ${digits.slice(3)}`;
})()}}

